#!/usr/bin/env bash
#
# AIRA AI 2026 — PR #96 Permanent Staging Cutover Wizard
# Generated by the /wizard skill.
#
# Walks repository owner (rajpunkeshwarrajgautam-boop) step by step through the
# 8 manual and owner-authorized stages of the permanent staging cutover.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit it.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

TOTAL_STAGES=8
_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()
WRITTEN_SECRET=()
SKIPPED=()

_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  This wizard guides you through the controlled permanent staging cutover\n' "$DIM"
  printf '  for PR #96 (feat/commercial-staging-integration -> staging).\n'
  printf '  It ensures recovery checkpoints, verifies exact commits, runs the controlled\n'
  printf '  historical identity import, and verifies all 11 integrity gates.%s\n\n' "$RESET"
  pause "Press Enter to start the staging cutover wizard..."
}

stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

say()  { printf '  %s\n' "$1"; }
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "Could not open browser automatically, please open: $url"
}

pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1
  fi
  printf '%s' "$value"
}

ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

finish() {
  _clear
  printf '\n%s%s  ✓ PR #96 Permanent Staging Cutover Protocol Complete!%s\n' "$BOLD" "$GREEN" "$RESET"
  note "Schema migrations 016–022 applied, historical identities imported, and all 11 integrity assertions verified."
  note "Permanent staging is live and certified at https://staging.virexaaiventures.com."
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: Authoritative Staging Cutover Procedure
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

banner "AIRA AI 2026 — PR #96 Permanent Staging Cutover"

# ── Stage 1: Verify PR #96 Candidate SHA & Release Authorization ───────────
stage "Verify PR #96 & Authorization"
say "Confirm the exact PR #96 HEAD commit SHA and ensure all CI checks passed."
open_url "https://github.com/rajpunkeshwarrajgautam-boop/AIRA-AI-2026/pull/96"
step "Verify that PR #96 is targeting branch: staging"
step "Verify that the Fast CI and Main / PR certification check runs have succeeded"

LOCAL_SHA=$(git rev-parse HEAD 2>/dev/null || echo "")
say "Current local HEAD commit:  ${LOCAL_SHA:-unknown}"

# Fetch remote PR #96 HEAD from GitHub API or git remote
REMOTE_SHA=""
if command -v gh >/dev/null 2>&1; then
  REMOTE_SHA=$(gh pr view 96 --json headRefOid -q .headRefOid 2>/dev/null || echo "")
fi
if [[ -z "$REMOTE_SHA" ]]; then
  REMOTE_SHA=$(git ls-remote origin feat/commercial-staging-integration 2>/dev/null | awk '{print $1}')
fi
say "Current remote PR #96 HEAD:  ${REMOTE_SHA:-unknown}"

ask APPROVED_SHA "Enter explicitly approved 40-character PR #96 commit SHA:"

if [[ ! "$APPROVED_SHA" =~ ^[0-9a-fA-F]{40}$ ]]; then
  warn "SECURITY FATAL: Approved SHA must be an exact 40-character hexadecimal string! Got: '$APPROVED_SHA'"
  exit 1
fi

if [[ -n "$LOCAL_SHA" && "$APPROVED_SHA" != "$LOCAL_SHA" ]]; then
  warn "SECURITY FATAL: Approved SHA ($APPROVED_SHA) does not match local git HEAD ($LOCAL_SHA)!"
  exit 1
fi

if [[ -n "$REMOTE_SHA" && "$APPROVED_SHA" != "$REMOTE_SHA" ]]; then
  warn "SECURITY FATAL: Approved SHA ($APPROVED_SHA) does not match remote PR #96 HEAD ($REMOTE_SHA)!"
  exit 1
fi

if [[ -n "$LOCAL_SHA" && -n "$REMOTE_SHA" && "$LOCAL_SHA" != "$REMOTE_SHA" ]]; then
  warn "SECURITY FATAL: Local git HEAD ($LOCAL_SHA) does not match remote PR #96 HEAD ($REMOTE_SHA)!"
  exit 1
fi

say "✓ Exact 40-character commit SHA verified and synchronized: $APPROVED_SHA"

if ! confirm "Do you authorize proceeding with the permanent staging cutover for this exact commit?"; then
  warn "Cutover aborted by owner. No changes made."
  exit 1
fi

# ── Stage 2: Create Neon Point-in-Time Recovery Checkpoint ─────────────────
stage "Create Staging Recovery Checkpoint"
say "Create an isolated point-in-time recovery branch in Neon project mute-frost-50372225."
say "This guarantees instant rollback capability before permanent staging schema migration."
open_url "https://console.neon.tech/app/projects/mute-frost-50372225/branches"
step "Branch Name: staging-backup-pre-commercial-cutover (or custom name/id)"
step "Parent Branch: main (br-autumn-star-b36dfu5w)"

ask CHECKPOINT_NAME "Enter Neon recovery checkpoint branch name or ID:"
CHECKPOINT_NAME="${CHECKPOINT_NAME:-staging-backup-pre-commercial-cutover}"

say "Running machine verification of Neon recovery checkpoint..."
if ! npx tsx scripts/verify-neon-checkpoint.ts "$CHECKPOINT_NAME"; then
  warn "SECURITY FATAL: Neon recovery checkpoint verification failed! Aborting cutover fail-closed."
  exit 1
fi

note "✓ Machine-verifiable Neon recovery checkpoint confirmed active."
pause "Press Enter to proceed to staging write isolation..."

# ── Stage 3: Staging Maintenance Barrier & Write Isolation ──────────────────
stage "Staging Maintenance Barrier & Write Isolation Gate"
say "Activate the authoritative staging maintenance barrier on permanent staging."
say "This enforces read-only defaults and table triggers to block background writers and older deployments."
step "Announce temporary maintenance on staging.virexaaiventures.com"

ask_secret STAGING_DB_URL "Paste permanent staging DATABASE_URL to verify write isolation:"

if confirm "Activate the staging-only maintenance barrier now?"; then
  say "Activating database maintenance barrier..."
  STAGING_DB_URL="$STAGING_DB_URL" npx tsx scripts/staging-maintenance-control.ts --activate
fi

say "Probing staging database write isolation across all 5 mandatory release gates..."
if ! STAGING_DB_URL="$STAGING_DB_URL" npx tsx scripts/verify-staging-write-isolation.ts "$STAGING_DB_URL"; then
  warn "SECURITY FATAL: Staging write isolation gate failed! All 5 release-blocking gates must PASS."
  warn "Cutover aborted fail-closed to prevent race conditions."
  exit 1
fi

note "✓ All 5 staging write isolation gates verified PASS."
pause "Press Enter to proceed to merge authorization..."

# ── Stage 4: Merge PR #96 into staging ────────────────────────────────────
stage "Merge PR #96 into staging (Vercel Build & Migrations)"
say "Merging PR #96 into staging triggers the automated Vercel preview deployment."
say "vercel.json buildCommand executes: scripts/staging-db-guard.ts && npm run db:migrate && npm run db:verify:deploy"
open_url "https://github.com/rajpunkeshwarrajgautam-boop/AIRA-AI-2026/pull/96"
step "Click 'Merge pull request' (or Rebase and merge) on PR #96"
step "Monitor the Vercel deployment at: https://vercel.com/rajpunkeshwarrajgautam-boops-projects/aira-ai-2026"
step "Confirm Vercel build output logs: 'knex migrate:latest' applied migrations 016 through 022"
pause "Press Enter once the Vercel deployment is READY on staging..."

# ── Stage 5: Execute Controlled Historical Identity Import ────────────────
stage "Execute Controlled Historical Identity Import"
say "Run the separate, transaction-backed historical identity import script."
say "This reconciles verified maintainer Google/GitHub social accounts, billing customers, and credit wallets."
if [[ -z "${STAGING_DB_URL:-}" ]]; then
  step "Obtain permanent staging DATABASE_URL from Neon console or Vercel env"
  ask_secret STAGING_DB_URL "Paste permanent staging DATABASE_URL (mute-frost-50372225 main):"
fi

step "Obtain verified Commercial PR #92 source DATABASE_URL (mute-frost-50372225 pr92-commercial-platform-isolated):"
ask_secret SOURCE_DB_URL "Paste Commercial PR #92 source DATABASE_URL:"

say "Running import in atomic transaction with authoritative Neon identity guards..."
if ! AIRA_ALLOW_STAGING_LIVE_IMPORT=true SOURCE_DB_URL="$SOURCE_DB_URL" TARGET_DB_URL="$STAGING_DB_URL" \
  npx tsx scripts/import-verified-commercial-identities.ts "$STAGING_DB_URL"; then
  warn "SECURITY FATAL: Controlled historical identity import failed! Aborting."
  exit 1
fi

note "Historical identity import completed cleanly."
pause "Press Enter to proceed to integrity verification..."

# ── Stage 6: Verify Staging Cutover Integrity ─────────────────────────────
stage "Verify Staging Cutover Integrity"
say "Running comprehensive 11-rule data integrity and continuity verification against permanent staging..."

if ! TARGET_DB_URL="$STAGING_DB_URL" AIRA_ALLOW_STAGING_LIVE_IMPORT=true \
  npx tsx scripts/staging-cutover-orchestrator.ts --verify-integrity "$STAGING_DB_URL"; then
  warn "SECURITY FATAL: Staging cutover integrity verification failed! One or more of the 11 gates did not pass."
  exit 1
fi

note "✓ All 11 cutover integrity gates certified!"
pause "Press Enter to proceed to deployment certification..."

# ── Stage 7: Permanent Staging CI Pipeline Attestation ────────────────────
stage "Permanent Staging CI Pipeline Attestation"
say "Verify that GitHub Actions Permanent Staging Pipeline has certified the release."
open_url "https://github.com/rajpunkeshwarrajgautam-boop/AIRA-AI-2026/actions/workflows/staging-deployment.yml"
step "Check that 'Permanent Staging Pipeline' workflow ran for the staging merge commit"
step "Verify that job 'Permanent Staging Deployment & Certification' passed"
step "Confirm artifact 'aira-staging-certification' is uploaded"
pause "Press Enter once CI attestation is confirmed green..."

# ── Stage 8: Real-Browser Acceptance & Unlock ─────────────────────────────
stage "Real-Browser Acceptance & Unlock"
say "Perform live browser acceptance testing on permanent staging."
open_url "https://staging.virexaaiventures.com"
step "1. Click 'Sign In' and authenticate with verified Google or GitHub account"
step "2. Confirm credit balance displays 100 credits (1:1 wallet continuity)"
step "3. Open previous conversation and verify historical messages are visible"
step "4. Send a test message and verify streaming response"
step "5. Deactivate maintenance barrier to restore normal staging traffic"

if confirm "Did real-browser acceptance succeed completely?"; then
  say "Deactivating permanent staging maintenance barrier..."
  if [[ -n "${STAGING_DB_URL:-}" ]]; then
    STAGING_DB_URL="$STAGING_DB_URL" npx tsx scripts/staging-maintenance-control.ts --deactivate
  fi
  note "✓ Real-browser acceptance certified and maintenance barrier cleanly deactivated."
  finish
else
  warn "❌ RELEASE NOT CERTIFIED — Real-browser acceptance failed or was rejected by owner!"
  warn "Cutover aborted. Do not declare release complete. Follow rollback to Neon recovery checkpoint if needed."
  exit 1
fi
}

run_wizard "$@"; exit
